package wordcount

import "testing"

func TestCountWords(t *testing.T) {
	tests := []struct {
		input string
		want  int
	}{
		{"", 0},
		{"hello", 1},
		{"hello world", 2},
		{"  spaces  ", 1},
		{"one two three four", 4},
	}
	for _, tc := range tests {
		if got := CountWords(tc.input); got != tc.want {
			t.Errorf("CountWords(%q) = %d, want %d", tc.input, got, tc.want)
		}
	}
}

func TestCountLines(t *testing.T) {
	tests := []struct {
		input string
		want  int
	}{
		{"", 0},
		{"one line", 1},
		{"line1\nline2", 2},
		{"line1\nline2\n", 2},
		{"a\nb\nc", 3},
	}
	for _, tc := range tests {
		if got := CountLines(tc.input); got != tc.want {
			t.Errorf("CountLines(%q) = %d, want %d", tc.input, got, tc.want)
		}
	}
}

func TestMostFrequent(t *testing.T) {
	tests := []struct {
		input string
		want  string
	}{
		{"", ""},
		{"the cat sat on the mat", "the"},
		{"Go go GO", "go"},
		{"apple banana apple cherry banana apple", "apple"},
	}
	for _, tc := range tests {
		if got := MostFrequent(tc.input); got != tc.want {
			t.Errorf("MostFrequent(%q) = %q, want %q", tc.input, got, tc.want)
		}
	}
}
